import sympy
from sympy.abc import x

def is_poly_in_Zx(p):
    try:
        p_expr = sympy.sympify(p)
        if not p_expr.free_symbols.issubset({x}):
            return False
        poly = sympy.Poly(p_expr, x, domain='ZZ')
        return True
    except Exception:
        return False

def is_isomorphic_to_Zi(witness):
    try:
        exprs = [sympy.sympify(p) for p in witness]
        polys = [sympy.Poly(p, x, domain='ZZ') for p in exprs if p != 0]
        if not polys:
            return False
            
        # The ideal must be generated by a single polynomial of the form x^2 - 2ux + u^2 + 1
        # We can find the GCD over QQ (SymPy's gcd over ZZ returns the primitive part)
        g = polys[0]
        for p in polys[1:]:
            g = g.gcd(p)
            
        if g.degree() != 2:
            return False
            
        coeffs = g.all_coeffs()
        if len(coeffs) != 3:
            return False
            
        a, b, c = coeffs
        if a == -1:
            a, b, c = -a, -b, -c
            
        if a != 1:
            return False
            
        if b % 2 != 0:
            return False
            
        u = -b // 2
        if c != u**2 + 1:
            return False
            
        # If the witness is just a single polynomial, it generates the ideal
        if len(polys) == 1:
            return True
            
        # If there are multiple generators, we check if the ideal is exactly (g) over ZZ
        gb = sympy.groebner(exprs, x, domain='ZZ')
        gb_polys = list(gb)
        if len(gb_polys) == 1:
            gen = sympy.Poly(gb_polys[0], x, domain='ZZ')
            if gen.degree() == 2 and abs(gen.LC()) == 1:
                return True
                
        return False
    except Exception:
        return False

def conditions(witness):
    try:
        # H1: witness represents an ideal in Z[x]
        # It can be a single polynomial or a list/tuple of polynomials
        if is_poly_in_Zx(witness):
            witness_list = [witness]
            h1 = True
        elif isinstance(witness, (list, tuple)) and len(witness) > 0:
            witness_list = list(witness)
            h1 = all(is_poly_in_Zx(p) for p in witness_list)
        else:
            witness_list = []
            h1 = False
    except Exception:
        h1 = False
        witness_list = []

    try:
        # neg_Q: R/I is NOT isomorphic to Z[i]
        if not h1:
            neg_q = False
        else:
            neg_q = not is_isomorphic_to_Zi(witness_list)
    except Exception:
        neg_q = False

    return [h1, neg_q]

CONDITION_LABELS = [
    "H_1: I is an ideal in the polynomial ring over Z",
    "¬Q: R/I is not isomorphic to the Gaussian integers"
]

